def load_logo_image(size=None):
    # v1.0.12d: ALWAYS try embedded first for other windows (new logo), tray uses old WiFi separately
    try:
        import base64, io
        from PIL import Image
        data = base64.b64decode(EMBEDDED_LOGO_B64)
        img = Image.open(io.BytesIO(data)).convert("RGBA")
        if size:
            img = img.resize((size, size), Image.LANCZOS)
        return img
    except Exception as e:
        # Fallback to files
        for cand in [LOGO_FILE, os.path.join(APP_DIR, "logo.png"), os.path.join(os.path.dirname(os.path.abspath(sys.argv[0])), "sanda_logo.png")]:
            if os.path.exists(cand):
                try:
                    from PIL import Image
                    img = Image.open(cand).convert("RGBA")
                    if size:
                        img = img.resize((size, size), Image.LANCZOS)
                    return img
                except Exception:
                    continue
    return None

def draw_sanda_logo(size=64, is_on=True):
    """Tray icon ONLY - old WiFi that turns blue when ON, red when OFF (matches YouTube video)"""
    from PIL import Image, ImageDraw, ImageFont
    img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)
    cx, cy = size // 2, size // 2
    draw.ellipse([2, 2, size - 2, size - 2], fill=(13, 17, 23, 255), outline=(255, 255, 255, 40), width=1)
    wave_color = (0, 201, 255, 255) if is_on else (255, 107, 107, 255)
    dot_color = (0, 255, 136, 255) if is_on else (255, 107, 107, 255)
    for arc_r, arc_w in [(int(size * 0.38), 3), (int(size * 0.27), 2), (int(size * 0.16), 2)]:
        x0 = cx - arc_r
        y0 = cy - arc_r + int(size * 0.05)
        x1 = cx + arc_r
        y1 = cy + arc_r + int(size * 0.05)
        draw.arc([x0, y0, x1, y1], start=210, end=330, fill=wave_color, width=arc_w)
    dot_r = int(size * 0.07)
    draw.ellipse([cx - dot_r, cy + int(size * 0.1) - dot_r, cx + dot_r, cy + int(size * 0.1) + dot_r], fill=dot_color)
    try:
        font_small = ImageFont.truetype("arialbd.ttf", int(size * 0.22))
    except Exception:
        font_small = ImageFont.load_default()
    bbox = draw.textbbox((0, 0), "S", font=font_small)
    tw = bbox[2] - bbox[0]
    th = bbox[3] - bbox[1]
    draw.text((cx - tw // 2, size - th - int(size * 0.08)), "S", fill=wave_color, font=font_small)
    return img



def draw_sanda_logo_with_text(width=380, height=110):
    from PIL import Image, ImageDraw, ImageFont
    img = Image.new("RGBA", (width, height), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)
    logo_img = load_logo_image(90)
    if logo_img:
        img.paste(logo_img, (10, (height - 90) // 2), logo_img)
        text_x = 115
    else:
        text_x = 20
    try:
        font_title = ImageFont.truetype("arialbd.ttf", 26)
        font_tag = ImageFont.truetype("arial.ttf", 11)
        font_ver = ImageFont.truetype("arial.ttf", 10)
    except Exception:
        font_title = ImageFont.load_default()
        font_tag = font_title
        font_ver = font_title
    draw.text((text_x, 12), APP_BRAND_NAME, fill=(0, 201, 255, 255), font=font_title)
    draw.text((text_x + 2, 48), APP_TAGLINE, fill=(139, 148, 158, 255), font=font_tag)
    draw.text((text_x + 2, 66), f"Version {APP_VERSION}  •  By {APP_AUTHOR}", fill=(139, 148, 158, 200), font=font_ver)
    return img




# ============================================
# ADMIN CHECK
# ============================================
def is_admin():
    try:
        return ctypes.windll.shell32.IsUserAnAdmin()
    except Exception:
        return False

def request_admin():
    if not is_admin():
        ctypes.windll.shell32.ShellExecuteW(
            None, "runas", sys.executable,
            f'"{os.path.abspath(sys.argv[0])}"',
            None, 1
        )
        sys.exit(0)

