class PCCleanerWindow:
    def __init__(self):
        self.window      = None
        self._mini_photo = None
        self._running    = False

    def open(self):
        if (self.window
                and tk.Toplevel.winfo_exists(
                    self.window)):
            self.window.focus_force()
            self.window.lift()
            return
        self.window = tk.Toplevel()
        self.window.title(
            f"{APP_BRAND_NAME} — PC Cleaner")
        self.window.geometry("680x580")
        self.window.configure(bg=APP_COLOR_BG)
        self.window.resizable(True, True)
        self._build_ui()

    def _build_ui(self):
        # ── Header ───────────────────────────
        header = tk.Frame(
            self.window,
            bg=APP_COLOR_BG2,
            pady=12, padx=15)
        header.pack(fill=tk.X)
        # v1.0.12h: Use new logo for other windows (not tray old WiFi)
