class LogWindow:
    def __init__(self):
        self.window      = None
        self._mini_photo = None

    def open(self):
        if (self.window
                and tk.Toplevel.winfo_exists(
                    self.window)):
            self.window.focus_force()
            self.window.lift()
            return
        self.window = tk.Toplevel()
        self.window.title(
            f"{APP_BRAND_NAME} — Activity Log")
        self.window.geometry("700x520")
        self.window.configure(bg=APP_COLOR_BG)
        self.window.resizable(True, True)

        header = tk.Frame(
            self.window,
            bg=APP_COLOR_BG2,
            pady=12, padx=15)
        header.pack(fill=tk.X)

        # v1.0.12h: Use new logo for other windows (not tray old WiFi)
        logo_img = load_logo_image(36)
        if logo_img:
            mini_icon = logo_img
        else:
            mini_icon = draw_sanda_logo(32, is_on=True)
        self._mini_photo = ImageTk.PhotoImage(
            mini_icon, master=self.window)
        tk.Label(
            header,
            image=self._mini_photo,
            bg=APP_COLOR_BG2
        ).pack(side=tk.LEFT, padx=(0, 8))
        tk.Label(
            header,
            text="Activity Log",
            font=("Segoe UI", 13, "bold"),
            fg=APP_COLOR_PRIMARY,
            bg=APP_COLOR_BG2
        ).pack(side=tk.LEFT)

        btn_frame = tk.Frame(
            header, bg=APP_COLOR_BG2)
        btn_frame.pack(side=tk.RIGHT)

        for text, cmd, color in [
            ("🔄 Refresh",
             self._refresh,
             APP_COLOR_BG3),
            ("🗑️ Clear",
             self._clear,
             APP_COLOR_ACCENT),
            ("📂 Open Folder",
             lambda: os.startfile(APP_DIR),
             APP_COLOR_BG3),
        ]:
            tk.Button(
                btn_frame,
                text=text,
                font=("Segoe UI", 8),
                bg=color,
                fg=APP_COLOR_TEXT,
                relief=tk.FLAT,
                padx=10, pady=4,
                cursor="hand2",
                command=cmd
            ).pack(side=tk.LEFT, padx=3)

        text_frame = tk.Frame(
            self.window, bg=APP_COLOR_BG)
        text_frame.pack(
            fill=tk.BOTH, expand=True,
            padx=12, pady=12)

        self.text = scrolledtext.ScrolledText(
            text_frame,
            font=("Consolas", 9),
            bg=APP_COLOR_BG2,
            fg=APP_COLOR_SUCCESS,
            wrap=tk.WORD,
            relief=tk.FLAT,
            padx=12, pady=8,
            insertbackground=APP_COLOR_PRIMARY
        )
        self.text.pack(fill=tk.BOTH, expand=True)
        self._refresh()

    def _refresh(self):
        try:
            with open(LOG_FILE, "r") as f:
                content = f.read()
        except FileNotFoundError:
            content = (
                f"Welcome to {APP_BRAND_NAME}!\n"
                f"No activity logged yet.")
        self.text.configure(state=tk.NORMAL)
        self.text.delete(1.0, tk.END)
        self.text.insert(tk.END, content)
        self.text.see(tk.END)
        self.text.configure(state=tk.DISABLED)

    def _clear(self):
        if messagebox.askyesno(
            "Clear Log",
            "Clear the entire activity log?",
            parent=self.window
        ):
            clear_log()
            self._refresh()

# ============================================
# APPS MANAGER WINDOW
# ============================================

class AppsManagerWindow:
    def __init__(self):
        self.window = None
        self.apps = []
        self.vars = []

    def open(self):
        if self.window and self.window.winfo_exists():
            self.window.focus_force()
            return
        self.window = tk.Toplevel()
        self.window.title(f"{APP_BRAND_NAME} — Manage Blocked Apps")
        self.window.geometry("820x500")
        self.window.configure(bg=APP_COLOR_BG)
        self.apps = load_blocked_apps()
        if not self.apps:
            self.apps = DEFAULT_BLOCKED_APPS.copy()
            save_blocked_apps(self.apps)
        self._build_ui()
        self._populate_list()

    def _build_ui(self):
        # Header with new logo (v1.0.12i)
        header = tk.Frame(self.window, bg=APP_COLOR_BG2, pady=10, padx=15)
        header.pack(fill=tk.X)
        # New logo for header
        try:
            logo_img = load_logo_image(36)
            if logo_img:
                from PIL import ImageTk
                self._header_photo = ImageTk.PhotoImage(logo_img, master=self.window)
                tk.Label(header, image=self._header_photo, bg=APP_COLOR_BG2).pack(side=tk.LEFT, padx=(0, 10))
        except Exception:
            pass
        tk.Label(header, text="Manage Blocked Apps", font=("Segoe UI", 12, "bold"), fg=APP_COLOR_PRIMARY, bg=APP_COLOR_BG2).pack(side=tk.LEFT)

        # Filter + Search frame - simple + full registry search
        filter_frame = tk.Frame(self.window, bg=APP_COLOR_BG, pady=5, padx=12)
        filter_frame.pack(fill=tk.X)
        tk.Label(filter_frame, text="Filter/Search:", bg=APP_COLOR_BG, fg=APP_COLOR_TEXT).pack(side=tk.LEFT)
        self.search_entry = tk.Entry(filter_frame, width=18)
        self.search_entry.pack(side=tk.LEFT, padx=8)
        self.search_entry.bind("<KeyRelease>", lambda e: self._filter_list())
        tk.Button(filter_frame, text="Clear", command=self._clear_filter).pack(side=tk.LEFT, padx=3)
        tk.Button(filter_frame, text="Search", bg="#00C9FF", fg="#0D1117", command=self._do_search).pack(side=tk.LEFT, padx=3)
        tk.Button(filter_frame, text="Scan All", bg="#21262D", fg="#E6EDF3", command=self._scan_all_fast).pack(side=tk.LEFT, padx=3)
        self.btn_stop = tk.Button(filter_frame, text="⏹ Stop", bg="#8B0000", fg="white", font=("Segoe UI", 9, "bold"), command=self._stop_search, state=tk.DISABLED)
        self.btn_stop.pack(side=tk.LEFT, padx=3)
        tk.Button(filter_frame, text="Reset", bg=APP_COLOR_WARNING, fg=APP_COLOR_BG, command=self._reset_defaults).pack(side=tk.LEFT, padx=5)
        self.search_status = tk.Label(filter_frame, text=f"{len(self.apps)} apps", bg=APP_COLOR_BG, fg=APP_COLOR_MUTED)
        self.search_status.pack(side=tk.LEFT, padx=5)

        # Simple list frame - NO CANVAS, guaranteed visible
        self.scroll_frame = tk.Frame(self.window, bg=APP_COLOR_BG2)
        self.scroll_frame.pack(fill=tk.BOTH, expand=True, padx=12, pady=5)

        # Buttons
        btn_frame = tk.Frame(self.window, bg=APP_COLOR_BG, pady=10)
        btn_frame.pack(fill=tk.X, padx=12)
        tk.Button(btn_frame, text="Save Changes", bg=APP_COLOR_SUCCESS, fg=APP_COLOR_BG, command=self._save).pack(side=tk.RIGHT, padx=5)
        tk.Button(btn_frame, text="Cancel", bg=APP_COLOR_BG3, fg=APP_COLOR_TEXT, command=self.window.destroy).pack(side=tk.RIGHT, padx=5)

    def _filter_list(self):
        query = self.search_entry.get().lower().strip()
        self._populate_list(filter_query=query)

    def _clear_filter(self):
        self.search_entry.delete(0, tk.END)
        self._populate_list()

    def _do_search(self):
        query = self.search_entry.get().strip()
        if not query:
            from tkinter import messagebox
            messagebox.showwarning("Enter Search Term", "Please enter an app name to search for.", parent=self.window)
            return
        self.search_status.config(text=f"Searching for '{query}'...")
        try:
            self.btn_stop.config(state=tk.NORMAL)
        except Exception:
            pass
        self.window.update()
        try:
            results = search_installed_apps(query)
            self._display_search_results(results, query)
        except Exception as e:
            self.search_status.config(text=f"Search error: {e}")
            write_log(f"Search error: {e}")

    def _scan_all_fast(self):
        self.search_status.config(text="Scanning registry...")
        try:
            self.btn_stop.config(state=tk.NORMAL)
        except Exception:
            pass
        self.window.update()
        try:
            results = search_installed_apps("")
            self.search_status.config(text=f"Found {len(results)} installed apps")
            from tkinter import messagebox
            messagebox.showinfo("Scan Complete", f"Found {len(results)} installed apps.\nUse Filter to find specific app in blocked list, or Search box to search registry.", parent=self.window)
        except Exception as e:
            self.search_status.config(text=f"Scan error: {e}")


    def _display_search_results(self, results, query):
        # Clear previous results display in status, for minimal version just show count and offer first
        if not results:
            self.search_status.config(text=f"No results for '{query}'")
            return
        self.search_status.config(text=f"Found {len(results)} - showing {min(10, len(results))}")
        # For minimal, add first result not already in list
        try:
            for app in results[:3]:
                if app["path"].lower() not in [a["path"].lower() for a in self.apps]:
                    self.apps.append(app)
                    break
            import json, os
            try:
                save_blocked_apps(self.apps)
            except Exception:
                pass
            self._populate_list()
        except Exception as e:
            self.search_status.config(text=f"Display error: {e}")

    def _add_from_search(self, app):
        if app["path"].lower() in [a["path"].lower() for a in self.apps]:
            return
        self.apps.append(app)
        try:
            save_blocked_apps(self.apps)
        except Exception:
            pass
        self._populate_list()
        self.search_status.config(text=f"Added {app['name']}")



    def _stop_search(self):
        self.search_status.config(text="Stopped")


    def _populate_list(self, filter_query=""):
        try:
            for widget in self.scroll_frame.winfo_children():
                widget.destroy()
        except Exception:
            pass
        self.vars = []
        # Headers
        hdr = tk.Frame(self.scroll_frame, bg=APP_COLOR_BG2)
        hdr.pack(fill=tk.X, pady=2)
        tk.Label(hdr, text="App Name", width=20, anchor="w", bg=APP_COLOR_BG2, fg=APP_COLOR_PRIMARY, font=("Segoe UI", 9, "bold")).pack(side=tk.LEFT, padx=5)
        tk.Label(hdr, text="Path", width=50, anchor="w", bg=APP_COLOR_BG2, fg=APP_COLOR_PRIMARY, font=("Segoe UI", 9, "bold")).pack(side=tk.LEFT, padx=5)

        filtered = self.apps
        if filter_query:
            filtered = [a for a in self.apps if filter_query in a["name"].lower()]

        if not filtered:
            tk.Label(self.scroll_frame, text="No apps - Click Reset to Defaults", bg=APP_COLOR_BG2, fg=APP_COLOR_ACCENT).pack(pady=10)
            return

        for i, app in enumerate(filtered[:20]):
            row = tk.Frame(self.scroll_frame, bg=APP_COLOR_BG2 if i%2==0 else APP_COLOR_BG3)
            row.pack(fill=tk.X, pady=1)
            var = tk.BooleanVar(value=app.get("enabled", True))
            self.vars.append(var)
            tk.Checkbutton(row, variable=var, bg=row["bg"]).pack(side=tk.LEFT, padx=5)
            tk.Label(row, text=app.get("name", "Unknown")[:20], width=20, anchor="w", bg=row["bg"], fg=APP_COLOR_TEXT).pack(side=tk.LEFT, padx=5)
            path_text = app.get("path", "")[-40:]
            tk.Label(row, text=path_text, width=50, anchor="w", bg=row["bg"], fg=APP_COLOR_MUTED, font=("Consolas", 7)).pack(side=tk.LEFT, padx=5)
            tk.Button(row, text="X", bg=row["bg"], fg=APP_COLOR_ACCENT, relief=tk.FLAT, command=lambda idx=i: self._delete_app(idx)).pack(side=tk.RIGHT, padx=5)

        self.search_status.config(text=f"{len(filtered)} / {len(self.apps)} apps")

    def _delete_app(self, idx):
        if 0 <= idx < len(self.apps):
            self.apps.pop(idx)
            self._populate_list()

    def _reset_defaults(self):
        self.apps = DEFAULT_BLOCKED_APPS.copy()
        save_blocked_apps(self.apps)
        self._populate_list()

    def _save(self):
        save_blocked_apps(self.apps)
        self.window.destroy()


class SandaDataSaverTray:
    def __init__(self):
        config          = load_config()
        self.is_on      = config.get(
            "data_saver_on", False)
        
        # Real-time Upgrade: Session activation tracker
        self.activation_time = time.time() if self.is_on else None
        
        self.log_win    = LogWindow()
        self.apps_win   = AppsManagerWindow()
        self.about_win  = AboutWindow()
        self.clean_win  = PCCleanerWindow()
        self.health_settings_win = HealthSettingsWindow()
        self.icon       = None

        self.root = tk.Tk()
        self.root.withdraw()
        self.root.title(APP_BRAND_NAME)
        self.health_manager = HealthReminderManager(self.root)
        self.root.withdraw()
        self.root.title(APP_BRAND_NAME)

    def get_estimated_saved_bytes(self):
        """
        Estimate saved bandwidth: 85 KB per second (~300 MB/hour)
        """
        if not self.is_on or not self.activation_time:
            return 0
        elapsed_seconds = time.time() - self.activation_time
        return int(elapsed_seconds * 85 * 1024)

    def _toggle(self, icon, item):
        def do_toggle():
            if self.is_on:
                # Log final stats before deactivating
                elapsed = time.time() - self.activation_time if self.activation_time else 0
                saved_bytes = int(elapsed * 85 * 1024)
                write_log(
                    f"Session closed. Duration: {elapsed/60:.1f} minutes. "
                    f"Est. Hotspot Data Saved: {bytes_to_readable(saved_bytes)}"
                )
                deactivate_data_saver(self.icon)
                self.is_on = False
                self.activation_time = None
            else:
                self.activation_time = time.time()
                activate_data_saver(self.icon)
                self.is_on = True
            self._refresh_icon()

        threading.Thread(
            target=do_toggle,
            daemon=True).start()

    def _open_log(self, icon, item):
        self.root.after(0, self.log_win.open)

    def _open_apps(self, icon, item):
        self.root.after(0, self.apps_win.open)

    def _open_about(self, icon, item):
        self.root.after(0, self.about_win.open)

    def _open_cleaner(self, icon, item):
        self.root.after(0, self.clean_win.open)

    def _open_health_settings(self, icon, item):
        try:
            self.root.after(0, self.health_settings_win.open)
        except Exception:
            pass

    def _restore_all(self, icon, item):
        def do_restore():
            restore_all_settings(self.icon)
            self.is_on = False
            self.activation_time = None
            self._refresh_icon()

        if messagebox.askyesno(
            "Restore All Settings",
            "This will turn OFF Sanda Data Saver and restore\nALL Windows settings to normal.\n\nContinue?"
        ):
            threading.Thread(
                target=do_restore,
                daemon=True).start()

    def _toggle_notifications(self, icon, item):
        config = load_config()
        config["notifications_enabled"] = \
            not config.get(
                "notifications_enabled", True)
        save_config(config)
        self._refresh_icon()

    def _toggle_auto_clean(self, icon, item):
        config = load_config()
        config["auto_clean_enabled"] = \
            not config.get(
                "auto_clean_enabled", False)
        save_config(config)
        write_log(f"Silent Auto-Cleaner set to {config['auto_clean_enabled']}")
        self._refresh_icon()

    def _refresh_icon(self):
        if self.icon:
            self.icon.icon  = draw_sanda_logo(
                64, self.is_on)
            
            # Real-time Upgrade: Estimate Saved Bandwidth displayed in Taskbar Title
            if self.is_on:
                saved_bytes = self.get_estimated_saved_bytes()
                saved_readable = bytes_to_readable(saved_bytes)
                self.icon.title = (
                    f"{APP_BRAND_NAME} — ON\n"
                    f"Est. Data Saved: {saved_readable}"
                )
            else:
                self.icon.title = f"{APP_BRAND_NAME} — OFF"
                
            self.icon.menu = self._build_menu()

    def _build_menu(self):
        config   = load_config()
        notif_on = config.get(
            "notifications_enabled", True)
        autoclean_on = config.get(
            "auto_clean_enabled", False)
        
        # Display dynamic calculated counter inside menu status
        if self.is_on:
            saved_bytes = self.get_estimated_saved_bytes()
            status_text = f"🟢 ACTIVE | Est. Saved: {bytes_to_readable(saved_bytes)}"
        else:
            status_text = "🔴 OFF — Normal Mode"

        toggle_text = (
            "🔓  Turn OFF Sanda Data Saver"
            if self.is_on else
            "🛡️  Turn ON Sanda Data Saver"
        )
        return pystray.Menu(
            pystray.MenuItem(
                APP_BRAND_NAME,
                lambda i, it: None,
                enabled=False),
            pystray.MenuItem(
                status_text,
                lambda i, it: None,
                enabled=False),
            pystray.Menu.SEPARATOR,
            pystray.MenuItem(
                toggle_text,
                self._toggle),
            pystray.Menu.SEPARATOR,
            pystray.MenuItem(
                "🧹  PC Cleaner",
                self._open_cleaner),
            pystray.MenuItem(
                "📋  Open Activity Log",
                self._open_log),
            pystray.MenuItem(
                "🚫  Manage Blocked Apps",
                self._open_apps),
            pystray.MenuItem(
                "ℹ️   About Sanda Data Saver",
                self._open_about),
            pystray.Menu.SEPARATOR,
            pystray.MenuItem(
                "💚  Health Reminder Settings",
                self._open_health_settings),
            pystray.MenuItem(
                "🔄  Restore All Settings",
                self._restore_all),
            pystray.MenuItem(
                "⚙️  Run on Windows Startup",
                toggle_startup,
                checked=lambda item: is_startup_enabled()),
            pystray.MenuItem(
                f"{'🕒' if autoclean_on else '🕒'}"
                f"  Silent Auto-Clean (24h): "
                f"{'On' if autoclean_on else 'Off'}",
                self._toggle_auto_clean),
            pystray.MenuItem(
                f"{'🔔' if notif_on else '🔕'}"
                f"  Notifications: "
                f"{'On' if notif_on else 'Off'}",
                self._toggle_notifications),
            pystray.Menu.SEPARATOR,
            pystray.MenuItem(
                "❌  Exit",
                self._exit),
        )

    def _auto_clean_loop(self):
        """
        Runs silent lightweight purge (Temp and Browsers) in the background every 24 hours.
        """
        # Wait 15 seconds after startup to settle down
        time.sleep(15)
        while True:
            config = load_config()
            if config.get("auto_clean_enabled", False):
                write_log("[Silent Auto-Cleaner] Starting background purge of temporary files and browser cache...")
                try:
                    freed_temp = safe_clean_folder(os.environ.get("TEMP", ""), "User Temp (Auto-Clean)")
                    freed_browser = clean_browser_caches()
                    total_freed = freed_temp + freed_browser
                    write_log(f"[Silent Auto-Cleaner] Purge completed. Silently freed {bytes_to_readable(total_freed)}.")
                except Exception as e:
                    write_log(f"[Silent Auto-Cleaner] Error: {e}")
            # Wait 24 hours
            time.sleep(86400)

    def _ui_refresh_loop(self):
        """
        Refreshes tray icon stats dynamically every 15 seconds when active
        """
        while True:
            time.sleep(15)
            if self.is_on:
                self._refresh_icon()

    def _exit(self, icon, item):
        if self.is_on:
            if not messagebox.askyesno(
                "Exit Warning",
                f"{APP_BRAND_NAME} is still ON.\n"
                "Exiting will NOT restore your services.\n\nExit anyway?"
            ):
                return
        write_log(
            f"{APP_BRAND_NAME} exited by user.")
        self.icon.stop()
        self.root.quit()

    def run(self):
        self.root.update()
        splash = SplashScreen(master=self.root)
        steps  = [
            ("Loading configuration...",      20),
            ("Reading blocked apps...",        40),
            ("Loading PC Cleaner...",          60),
            ("Preparing system tray...",       80),
            (f"Starting {APP_BRAND_NAME}...", 100),
        ]
        for text, val in steps:
            splash.update_status(text, val)
            time.sleep(0.4)
        splash.close()

        write_log(
            f"{APP_BRAND_NAME} v{APP_VERSION} started.")
        
        self.icon = pystray.Icon(
            APP_NAME,
            draw_sanda_logo(64, self.is_on),
            (f"{APP_BRAND_NAME} — ON"
             if self.is_on
             else f"{APP_BRAND_NAME} — OFF"),
            menu=self._build_menu()
        )
        
        # Start background threads for new upgrades
        threading.Thread(target=self._auto_clean_loop, daemon=True).start()
        threading.Thread(target=self._ui_refresh_loop, daemon=True).start()
        
        threading.Thread(
            target=self.icon.run,
            daemon=True).start()
        self.root.mainloop()

# ============================================
# ENTRY POINT
# ============================================
if __name__ == "__main__":
    if not is_admin():
        request_admin()
    app = SandaDataSaverTray()
    app.run()
